-- Scrollr schema baseline.
--
-- Squashed from the 38 migrations that previously lived in six separate
-- directories across five services (api/, channels/fantasy/api/, and the
-- finance/sports/rss/predictions Rust services). core-api is now the single
-- owner of every shared table (VISION 4.3); the ingesters are pure writers
-- and run no migrations.
--
-- Generated by applying that retired chain to an empty database and dumping
-- the result, so it is exactly the schema that chain produced -- with one
-- deliberate change: user_channels -> user_widgets and channel_type ->
-- widget_type (VISION 4.4). Scrollr has no users, so this is a straight
-- rename with no compatibility seam.
--
-- Write new migrations on top of this file; do not edit it.
-- business_leads (TABLE)

CREATE TABLE business_leads (
    id bigint NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    name text NOT NULL,
    email text NOT NULL,
    company text NOT NULL,
    use_case text NOT NULL,
    message text NOT NULL,
    ip_redacted text,
    user_agent text,
    notified_at timestamp with time zone,
    auto_replied_at timestamp with time zone,
    replied_at timestamp with time zone
);

CREATE SEQUENCE business_leads_id_seq
    START WITH 1
    INCREMENT BY 1
    NO MINVALUE
    NO MAXVALUE
    CACHE 1;

ALTER SEQUENCE business_leads_id_seq OWNED BY business_leads.id;

-- games (TABLE)

CREATE TABLE games (
    id integer NOT NULL,
    league character varying(50) NOT NULL,
    sport character varying(50) DEFAULT ''::character varying NOT NULL,
    external_game_id character varying(100) NOT NULL,
    link character varying(500),
    home_team_name character varying(100) NOT NULL,
    home_team_logo character varying(500),
    home_team_score integer,
    away_team_name character varying(100) NOT NULL,
    away_team_logo character varying(500),
    away_team_score integer,
    start_time timestamp with time zone NOT NULL,
    short_detail character varying(200),
    state character varying(50) NOT NULL,
    status_short character varying(20),
    status_long character varying(100),
    timer character varying(20),
    venue character varying(200),
    season character varying(20),
    created_at timestamp with time zone DEFAULT CURRENT_TIMESTAMP,
    updated_at timestamp with time zone DEFAULT CURRENT_TIMESTAMP,
    home_team_code character varying(10),
    away_team_code character varying(10)
);

CREATE SEQUENCE games_id_seq
    AS integer
    START WITH 1
    INCREMENT BY 1
    NO MINVALUE
    NO MAXVALUE
    CACHE 1;

ALTER SEQUENCE games_id_seq OWNED BY games.id;

-- markets (TABLE)

CREATE TABLE markets (
    id text NOT NULL,
    source text DEFAULT 'kalshi'::text NOT NULL,
    ticker text NOT NULL,
    event_ticker text,
    series_ticker text,
    category text,
    title text,
    subtitle text,
    yes_price integer,
    yes_bid integer,
    yes_ask integer,
    prev_yes_price integer,
    volume bigint,
    volume_24h bigint,
    open_interest bigint,
    status text,
    result text,
    is_primary boolean DEFAULT true NOT NULL,
    open_time timestamp with time zone,
    close_time timestamp with time zone,
    link text,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    event_title text DEFAULT ''::text NOT NULL,
    event_rank smallint DEFAULT 1 NOT NULL,
    in_sweep boolean DEFAULT true NOT NULL,
    settled_at timestamp with time zone
);

ALTER TABLE ONLY markets REPLICA IDENTITY FULL;

-- osticket_message_ids (TABLE)

CREATE TABLE osticket_message_ids (
    id bigint NOT NULL,
    ticket_number text NOT NULL,
    message_id text NOT NULL,
    recipient_email text NOT NULL,
    direction text NOT NULL,
    captured_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT osticket_message_ids_direction_check CHECK ((direction = ANY (ARRAY['outbound_osticket'::text, 'outbound_ai'::text, 'outbound_partner_notification'::text, 'inbound_user'::text, 'unknown'::text])))
);

CREATE SEQUENCE osticket_message_ids_id_seq
    START WITH 1
    INCREMENT BY 1
    NO MINVALUE
    NO MAXVALUE
    CACHE 1;

ALTER SEQUENCE osticket_message_ids_id_seq OWNED BY osticket_message_ids.id;

-- rss_items (TABLE)

CREATE TABLE rss_items (
    id integer NOT NULL,
    feed_url text NOT NULL,
    guid text NOT NULL,
    title text NOT NULL,
    link text DEFAULT ''::text NOT NULL,
    description text DEFAULT ''::text NOT NULL,
    source_name text DEFAULT ''::text NOT NULL,
    published_at timestamp with time zone,
    created_at timestamp with time zone DEFAULT CURRENT_TIMESTAMP NOT NULL,
    updated_at timestamp with time zone DEFAULT CURRENT_TIMESTAMP NOT NULL
);

CREATE SEQUENCE rss_items_id_seq
    AS integer
    START WITH 1
    INCREMENT BY 1
    NO MINVALUE
    NO MAXVALUE
    CACHE 1;

ALTER SEQUENCE rss_items_id_seq OWNED BY rss_items.id;

-- standings (TABLE)

CREATE TABLE standings (
    id integer NOT NULL,
    league character varying(50) NOT NULL,
    team_name character varying(100) NOT NULL,
    team_code character varying(10),
    team_logo character varying(500),
    rank integer,
    wins integer DEFAULT 0 NOT NULL,
    losses integer DEFAULT 0 NOT NULL,
    draws integer DEFAULT 0 NOT NULL,
    points integer,
    games_played integer DEFAULT 0 NOT NULL,
    goal_diff integer,
    description character varying(200),
    form character varying(20),
    group_name character varying(100),
    season character varying(20),
    updated_at timestamp with time zone DEFAULT CURRENT_TIMESTAMP,
    sport_api character varying(50),
    pct character varying(10),
    games_behind character varying(10),
    otl integer,
    goals_for integer,
    goals_against integer,
    points_for integer,
    points_against integer,
    streak character varying(10)
);

ALTER TABLE ONLY standings REPLICA IDENTITY FULL;

CREATE SEQUENCE standings_id_seq
    AS integer
    START WITH 1
    INCREMENT BY 1
    NO MINVALUE
    NO MAXVALUE
    CACHE 1;

ALTER SEQUENCE standings_id_seq OWNED BY standings.id;

