-- support_drafts (TABLE)

CREATE TABLE support_drafts (
    id bigint NOT NULL,
    ticket_number text NOT NULL,
    user_email text NOT NULL,
    user_name text,
    original_subject text NOT NULL,
    draft_body_html text NOT NULL,
    ai_summary text,
    ai_category text,
    ai_priority text,
    ai_channel text,
    ai_duplicate_of text,
    ai_confidence text,
    status text NOT NULL,
    edited_body_html text,
    decided_at timestamp with time zone,
    sent_at timestamp with time zone,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    osticket_thread_entry_id bigint,
    should_close boolean DEFAULT false NOT NULL,
    user_message_html text,
    CONSTRAINT support_drafts_status_check CHECK ((status = ANY (ARRAY['pending'::text, 'approved'::text, 'edited'::text, 'skipped'::text, 'sent'::text, 'failed'::text])))
);

CREATE SEQUENCE support_drafts_id_seq
    START WITH 1
    INCREMENT BY 1
    NO MINVALUE
    NO MAXVALUE
    CACHE 1;

ALTER SEQUENCE support_drafts_id_seq OWNED BY support_drafts.id;

